export function toCentimetres(raw) {
  const s = String(raw).trim().toLowerCase();
  const inch = s.match(/^(\d+(?:\.\d+)?)\s*(\"|in|zoll)$/);
  if (inch) return Math.round(Number(inch[1]) * 2.54);
  const cm = s.match(/^(\d+)\s*(cm)?$/);
  return cm ? Number(cm[1]) : null;
}

