import { frameKey } from './frame.js';

export function mergeByFrame(listings) {
  const seen = new Map();
  const rest = [];
  for (const l of listings) {
    const k = frameKey(l);
    if (!k) { rest.push(l); continue; }
    const prev = seen.get(k);
    if (!prev || l.seenAt > prev.seenAt) seen.set(k, l);
  }
  return [...seen.values(), ...rest];
}

