import sharp from 'sharp';

// 8x8 average hash of the first listing photo.
export async function averageHash(buf) {
  const px = await sharp(buf).resize(8, 8).grayscale().raw().toBuffer();
  const mean = px.reduce((a, b) => a + b, 0) / px.length;
  return [...px].map(p => (p > mean ? '1' : '0')).join('');
}

