import { hamming, SAME_PHOTO } from '../dedupe-photo/distance.js';

// Same bike on two marketplaces: matching photo and EUR price within 10%.
export function sameBike(a, b) {
  if (a.source === b.source) return false;
  const close = Math.abs(a.priceEur - b.priceEur) <= 0.1 * Math.max(a.priceEur, b.priceEur);
  return close && hamming(a.photoHash, b.photoHash) <= SAME_PHOTO;
}

