// Keep the cheapest copy and remember where else the bike is listed.
export function pickCheapest(group) {
  const [best, ...others] = [...group].sort((x, y) => x.priceEur - y.priceEur);
  return { ...best, alsoOn: others.map(o => o.source) };
}

