// Group listings by brand and model, ignoring case and the year.
export function modelKey(l) {
  return `${l.brand} ${l.model}`.toLowerCase().replace(/\b(19|20)\d{2}\b/, '').trim();
}

export function groupByModel(listings) {
  const out = new Map();
  for (const l of listings) out.set(modelKey(l), [...(out.get(modelKey(l)) ?? []), l]);
  return out;
}

