// Last known EUR price per listing, keyed by source:id.
export function recordPrice(history, l, now = Date.now()) {
  const key = `${l.source}:${l.id}`;
  const prev = history.get(key);
  history.set(key, { price: l.priceEur, at: now });
  return prev ?? null;
}

