// Sellers nudge prices daily; ignore drops under 5% or 10 EUR.
export const MIN_PCT = 0.05;
export const MIN_EUR = 10;

export function isSignificant({ from, to }) {
  return from - to >= MIN_EUR && (from - to) / from >= MIN_PCT;
}
